[8154] = { en = "Arathi Basin Mark of Honor!", tier = 4,
  t = "Arathi Basin Mark of Honor!",
  d = "Een oorlog moet je met soldaten voeren, dat zal elke soldaat je vertellen. Ze zullen ook zeggen dat een gevecht met slechte uitrusting of op een lege maag al verloren is voordat het begint!$B$BDaarom is Arathi Basin belangrijk. Er zijn belangrijke plekken in het dal met noodzakelijke grondstoffen. Metalen, wapens, voedsel, hout - alles is nodig, en alles is daar te krijgen.$B$BDat wil ik van je, $N. Ga Arathi Basin binnen, win de strijd door meer bases in handen te houden dan de vijand, en kom bij me terug met een Mark of Honor.",
  o = "Win de strijd om Arathi Basin, haal een Arathi Basin Mark of Honor en breng die naar Sergeant Maclear in Refuge Pointe.",
  p = "Heb je de Marks of Honor, $N? Zonder die marks kan de League of Arathor geen fatsoenlijk gevecht voeren...",
  c = "Je hebt de Mark! Goed gedaan! Ik stuur de grondstoffen naar onze kwartiermeesters, die ze snel onder onze troepen kunnen verdelen.$B$BDank je, $N. Succesvolle missies zoals die van jou: zo worden oorlogen echt gewonnen.",
