[8392] = { en = "Claiming Arathi Basin", tier = 4,
  t = "Arathi Basin veroveren",
  d = "Een oorlog winnen gaat om meer dan alleen slimmer zijn en beter vechten dan je tegenstander. De overwinning komt vaak gewoon neer op meer produceren dan je vijand.$B$BIn Arathi Basin ligt een flinke voorraad grondstoffen voor de kant die het als eerste weet te veroveren.$B$BAls de Alliance wint, betekent dat meer zwaarden en pieken voor onze troepen. Als de Horde zou winnen, zouden die zwaarden en pieken nog steeds gemaakt worden, alleen zouden ze dan op ons gericht zijn! Nu is het moment om de Alliance te helpen in Arathi Basin, $N.",
  o = "Breng 3 Arathi Basin Marks of Honor naar een Alliance Brigadier General buiten de slagvelden.",
  p = "De oorlog tegen de Horde put onze voorraden snel uit, $N. Het is van groot belang dat we Arathi Basin in handen houden, zodat de stroom grondstoffen blijft komen! Heb je al geholpen in Arathi?",
