[8081] = { en = "More Resource Crates", tier = 4,
  t = "Meer kisten met grondstoffen",
  d = "Een oorlog moet je met soldaten voeren, dat zal elke soldaat je vertellen. Ze zullen ook zeggen dat een gevecht met slechte uitrusting of op een lege maag al verloren is voordat het begint!$B$BDaarom is Arathi Basin belangrijk. Er zijn belangrijke plekken in het dal met noodzakelijke grondstoffen. Metalen, wapens, voedsel, hout - alles is nodig, en alles is daar te krijgen.$B$BDat wil ik van je, $N. Ga Arathi Basin binnen, win de strijd door meer bases in handen te houden dan de vijand, en kom bij me terug met een kist met grondstoffen.",
  o = "Win de strijd om Arathi Basin, haal een Arathi Resource Crate en breng die naar Sergeant Maclear in Refuge Pointe.",
  p = "$N, de League of Arathor heeft een vaste opdracht voor je: ga opnieuw Arathi Basin binnen, haal meer kisten met grondstoffen en breng ze naar mij.",
  c = "Heel goed. Ik breng deze meteen naar onze kwartiermeesters, en ik stuur een eervolle vermelding voor je daden naar mijn meerderen.$B$BNogmaals bedankt, $N. Je bijdragen aan onze strijd worden gezien door zowel voetsoldaat als veldmaarschalk.",
  g = { {"kisten", "crates (kist)"}, {"uitrusting", "gear, equipment"}, {"noodzakelijke", "essential (noodzakelijk)"}, {"grondstoffen", "resources (grondstof)"}, {"vaste opdracht", "standing mission"}, {"kwartiermeesters", "quartermasters (kwartiermeester)"}, {"eervolle vermelding", "commendation"}, {"daden", "deeds, actions (daad)"}, {"meerderen", "superiors (meerdere)"}, {"bijdragen", "contributions (bijdrage)"}, {"voetsoldaat", "footman"}, {"veldmaarschalk", "field marshal"} },
},

[8105] = { en = "The Battle for Arathi Basin!", tier = 4,
  t = "De strijd om Arathi Basin!",
  d = "$N, de strijd om Arathi Basin is een strijd om grondstoffen en gebied. Belangrijke punten in het gebied moeten worden vastgehouden en gebruikt om onze troepen te voorzien van broodnodige ruwe materialen en voorraden. Ik geef je de opdracht om de punten aan te vallen die het verst van onze basis in Arathi Basin liggen.$B$BVal de boerderij, de mijn, de houtzagerij en de smidse aan wanneer de vijand ze in handen heeft. Zoek de banier van de vijand en ruk hem van zijn vlaggenmast!$B$BAls je dit bij alle vier de punten hebt gedaan, kom dan terug bij mij.",
  o = "Val de mijn, de houtzagerij, de smidse en de boerderij aan, en ga dan terug naar Field Marshal Oslight in Refuge Pointe.",
  c = "Ik heb berichten ontvangen over je heldendaden in Arathi Basin, $n. Goed gedaan! Met mensen zoals jij die zich bij de strijd hier aansluiten, heb ik er vertrouwen in dat we op een dag ons thuisland zullen heroveren.",
  o1 = "Mijn aangevallen",
  o2 = "Houtzagerij aangevallen",
  o3 = "Smidse aangevallen",
  o4 = "Boerderij aangevallen",
  g = { {"grondstoffen", "resources (grondstof)"}, {"vastgehouden", "held (vasthouden)"}, {"te voorzien van", "to supply with (voorzien)"}, {"broodnodige", "much-needed (broodnodig)"}, {"ruwe", "raw (ruw)"}, {"houtzagerij", "lumber mill"}, {"smidse", "blacksmith, forge"}, {"banier", "banner"}, {"ruk", "rip, yank (rukken)"}, {"vlaggenmast", "flag post"}, {"heldendaden", "exploits, heroic deeds (heldendaad)"}, {"aansluiten", "to join"}, {"thuisland", "homeland"}, {"heroveren", "to retake"} },
},

