[8114] = { en = "Control Four Bases", tier = 4,
  t = "Vier bases in handen houden",
  d = "$N, je hebt de strijd om Arathi Basin naar onze vijanden gebracht en op dat slagveld grote eer verdiend. Je hebt ons laten zien wat je waard bent als $c, en je hebt onze vijanden laten zien dat we ons niet zullen onderwerpen aan hun kwaadaardigheid!$B$BOmdat je hebt bewezen hoe waardevol je voor ons bent, heb ik een moeilijke taak voor je. Ik wil dat je minstens vier van de bases in Arathi Basin verovert en vasthoudt. Als je dat kunt, dan beveiligen we niet alleen belangrijke grondstoffen, maar laten we de Horde ook zien dat wij de baas zijn!$B$BGa, $N, en veel geluk.",
  o = "Ga Arathi Basin binnen, verover vier bases en houd ze tegelijk in handen, en ga dan terug naar Field Marshal Oslight in Refuge Pointe.",
  c = "Heel goed werk, $n! Een opgewonden verkenner kwam bij me met een verslag van je heldendaden. Wij van de League of Arathor zijn erg tevreden!$b$bJe wordt snel een plaatselijke held onder de soldaten van de League, en de daad van vandaag bewijst opnieuw je uitstekende reputatie.",
  e = "Houd vier bases in handen.",
  g = { {"slagveld", "battlefield"}, {"eer", "honor"}, {"onderwerpen", "to submit"}, {"kwaadaardigheid", "villainy, malice"}, {"waardevol", "valuable"}, {"minstens", "at least"}, {"verovert", "capture (veroveren)"}, {"vasthoudt", "hold (vasthouden)"}, {"beveiligen", "to secure"}, {"de baas zijn", "to be the boss, dominate"}, {"opgewonden", "excited"}, {"verkenner", "scout"}, {"verslag", "report"}, {"plaatselijke", "local (plaatselijk)"}, {"daad", "deed"} },
},

[8115] = { en = "Control Five Bases", tier = 4,
  t = "Vijf bases in handen houden",
  d = "$N, vechten om de grondstoffen van Arathi Basin is een bloedige onderneming. Je diensten voor de League of Arathor zijn even hard nodig als ze gewaardeerd worden.$B$BEn we hebben nog één taak voor je.$B$BDe League wil één krachtige aanval doen tegen de bezetting van Arathi Basin door de Defilers. We willen ze van elk strategisch punt op het slagveld verdrijven!$B$BHet zal niet makkelijk zijn, maar als iemand het kan, ben jij het.",
  o = "Houd 5 bases in Arathi Basin tegelijk in handen, en ga dan terug naar Field Marshal Oslight in Refuge Pointe.",
  e = "Verover vijf bases.",
  g = { {"bloedige", "bloody (bloedig)"}, {"onderneming", "undertaking"}, {"diensten", "services (dienst)"}, {"gewaardeerd", "appreciated (waarderen)"}, {"krachtige", "strong, powerful (krachtig)"}, {"bezetting", "occupation"}, {"strategisch", "strategic"}, {"slagveld", "battlefield"}, {"verdrijven", "to drive out"} },
},

