[8524] = { en = "The Alliance Needs Rainbow Fin Albacore!", tier = 4,
  t = "De Alliance heeft Rainbow Fin Albacore nodig!",
  d = "Hé daar, vriend! Als ik tegen je zou zeggen: 'Vind jij niet dat soldaten net als iedereen eten moeten hebben?', dan zou je natuurlijk 'ja' antwoorden. Ik ben het 110% met je eens! Fijn dat we het eens zijn. Je hoeft alleen maar op pad te gaan, een hele hoop Raw Rainbow Fin Albacore op te vissen, die dan allemaal te koken en hier bij mij terug te brengen. Mmm, mmm, ik proef het al.",
  o = "Breng 20 Rainbow Fin Albacore naar Slicky Gastronome in de Military Ward in Ironforge.",
  p = "Ik durf te wedden dat je terug bent met al die Rainbow Fin Albacore waar we het eerder over hadden, toch, $c?",
  c = "Twee voor de Alliance, één voor mij, twee voor de Alliance, één voor mij. Hé daar, visboer, uitstekend werk. Ik zie dat je de club echt eer gaat aandoen. Maar het lijkt me dat we nog meer van die albacore nodig hebben. Waarom ga je er niet op uit om er nog een beetje meer bij elkaar te zoeken? Ik hoor mijn maag nu al rommelen.",
  g = { {"het met je eens", "agree with you"}, {"het eens zijn", "to be in agreement"}, {"op pad", "out, on the way"}, {"een hele hoop", "a whole lot"}, {"op te vissen", "to fish up (opvissen)"}, {"proef", "taste (proeven)"}, {"durf te wedden", "dare to bet (durven, wedden)"}, {"visboer", "fishmonger"}, {"eer gaat aandoen", "will be a credit to (eer aandoen)"}, {"bij elkaar te zoeken", "to gather up"}, {"maag", "stomach"}, {"rommelen", "to rumble"} },
},

[8525] = { en = "The Alliance Needs More Rainbow Fin Albacore!", tier = 4,
  t = "De Alliance heeft meer Rainbow Fin Albacore nodig!",
  d = "Wat! Jij weer? Nou, dan ben ik een aap... alleen ben ik een gnoom. Slicky Gastronome, om precies te zijn! Dus je bent terug om weer te helpen, hè? Nou, ik kan het je niet kwalijk nemen. Hou je niet gewoon van de geur van al dat eten? <kwijlt>$B$BGenoeg rondgehangen! Ga op pad en breng me meer Rainbow Fin Albacore!",
  o = "Breng 20 Rainbow Fin Albacore naar Slicky Gastronome op het vliegveld in Dun Morogh.",
  p = "Wat! Jij weer? Nou, dan ben ik een aap... alleen ben ik een gnoom. Slicky Gastronome, om precies te zijn! Dus je bent terug om weer te helpen, hè? Nou, ik kan het je niet kwalijk nemen. Hou je niet gewoon van de geur van al dat eten? <kwijlt>$B$BGenoeg rondgehangen! Ga op pad en breng me meer Rainbow Fin Albacore!",
  c = "Ik wist dat je het in je had, jochie. Je ziet eruit als iemand die weet wat $ghij:zij; leuk vindt. Om precies te zijn: dat je het leuk vindt om mij en de machthebbers tevreden te stellen. En dat is je gelukt, dat garandeer ik.$B$BHaha, oké, ik ga deze vissen even goed opbergen, en dan kunnen jij en ik een praatje maken over het verzamelen van nog twintig albacore.",
  g = { {"aap", "monkey"}, {"om precies te zijn", "to be precise"}, {"kwalijk nemen", "to blame"}, {"geur", "smell"}, {"kwijlt", "drools (kwijlen)"}, {"rondgehangen", "loitered (rondhangen)"}, {"jochie", "kid"}, {"machthebbers", "the powers that be (machthebber)"}, {"tevreden te stellen", "to please (tevredenstellen)"}, {"garandeer", "guarantee (garanderen)"}, {"opbergen", "to store away"}, {"een praatje maken", "to have a little talk"} },
},

[8526] = { en = "The Alliance Needs Roast Raptor!", tier = 4,
  t = "De Alliance heeft Roast Raptor nodig!",
  d = "O, hoe gaat het, $c? Ik zie dat je misschien eten wilt verzamelen voor de komende oorlog bij Ahn'Qiraj? Mijn vader dacht om de een of andere reden dat het een goede leerervaring voor me zou zijn als ik me hier als vrijwilliger zou aanmelden. Grote fout. Ik eet niet eens graag vlees.$B$BMaar goed, als je er zin in hebt, kun je me veel Roast Raptor brengen. Blijkbaar willen alle soldaten dat.",
  o = "Breng 20 Roast Raptor naar Sarah Sadwhistle in de Military Ward in Ironforge.",
  p = "Dus, heb je al die Roast Raptor al?",
  c = "Jeetje, wat geweldig. Bedankt dat je me al dit verbrande dierenvlees brengt, $c. Ik leg het daar wel op de stapel. Iemand zal er vast voor zorgen. Als je wat tijd over hebt, wil je me misschien nog meer brengen?",
  g = { {"komende", "coming, upcoming (komend)"}, {"om de een of andere reden", "for some reason"}, {"leerervaring", "learning experience"}, {"vrijwilliger", "volunteer"}, {"aanmelden", "to sign up"}, {"blijkbaar", "apparently"}, {"jeetje", "gee"}, {"verbrande", "burnt (verbrand)"}, {"dierenvlees", "animal flesh"}, {"stapel", "pile"} },
},

[8527] = { en = "The Alliance Needs More Roast Raptor!", tier = 4,
  t = "De Alliance heeft meer Roast Raptor nodig!",
  d = "Hoi weer, $c. Ik zie dat je hier heel enthousiast over bent. Dus je wilt me zeker nog twintig Roast Raptor brengen. Geweldig. Nou, doe dat maar. Ik zie je wel als je terug bent.",
  o = "Breng 20 Roast Raptor naar Sarah Sadwhistle op het vliegveld in Dun Morogh.",
  p = "Hoi weer, $c. Ik zie dat je hier heel enthousiast over bent. Dus je wilt me zeker nog twintig Roast Raptor brengen? Geweldig. Nou, doe dat maar. Ik zie je wel als je terug bent.",
  c = "Wauw, jij bent echt een doorzetter. Ik word al moe als ik naar je kijk. Maar goed, bedankt namens de Alliance en zo. Ik zorg ervoor dat al dat dode vlees wordt ingepakt. Je kunt later nog eens bij me langskomen om te zien of we er nog meer van nodig hebben, al begint het hier wel te stinken, als je het mij vraagt.",
  g = { {"enthousiast", "excited, enthusiastic"}, {"zeker", "surely, I suppose"}, {"doorzetter", "go-getter"}, {"namens", "on behalf of"}, {"en zo", "and all that"}, {"ingepakt", "packed away (inpakken)"}, {"langskomen", "to drop by, check back"}, {"al", "although (here)"}, {"stinken", "to stink"} },
},

[8528] = { en = "The Alliance Needs Spotted Yellowtail!", tier = 4,
  t = "De Alliance heeft Spotted Yellowtail nodig!",
  d = "Het lijkt misschien niet heldhaftig om gekookte vis te verzamelen, maar onderschat de waarde van voorbereiding niet, jonge $c. Soldaten moeten net als iedereen eten, en wij zijn hier om ons deel te doen, zodat ze hebben wat ze nodig hebben als de oorlog in Ahn'Qiraj begint.$B$BDaarom leg ik een voorraad Spotted Yellowtail aan. Het is een veelzijdige voedselbron die goed te bewaren is en in veel verschillende gerechten kan worden gebruikt. Hij heeft ook niet de geur van sommige andere zoutwatervissen. Wil je me helpen bij deze taak?",
  o = "Breng 20 Spotted Yellowtail naar Huntress Swiftriver in de Military Ward in Ironforge.",
  p = "Ik heb er vertrouwen in dat je zo snel terugkomt met de Spotted Yellowtail waar we het over hadden.",
  c = "Dank je voor dit geschenk, $C, en ook nog zo snel. Onze soldaten zullen zeker geen gebrek aan eten hebben. Laat me deze vissen eerst goed opbergen, en dan kunnen jij en ik het over een tweede vangst hebben, als je dat wilt.",
  g = { {"heldhaftig", "heroic"}, {"onderschat", "underestimate (onderschatten)"}, {"voorbereiding", "preparation"}, {"voorraad", "stock, supply (een voorraad aanleggen: to stockpile)"}, {"veelzijdige", "versatile (veelzijdig)"}, {"voedselbron", "source of food, sustenance"}, {"bewaren", "to keep, store"}, {"gerechten", "dishes (gerecht)"}, {"zoutwatervissen", "saltwater fish (zoutwatervis)"}, {"geschenk", "gift"}, {"gebrek", "lack, shortage"}, {"vangst", "catch, haul"} },
},

[8529] = { en = "The Alliance Needs More Spotted Yellowtail!", tier = 4,
  t = "De Alliance heeft meer Spotted Yellowtail nodig!",
  d = "Als je nog steeds wilt, stuur ik je graag opnieuw op pad om nog een vangst Spotted Yellowtail binnen te halen, $N. Met de ervaring die je de eerste keer hebt opgedaan, gaat deze vangst vast veel sneller en makkelijker. Doe je mee?",
  o = "Breng 20 Spotted Yellowtail naar Huntress Swiftriver op het vliegveld in Dun Morogh.",
  p = "Als je nog steeds wilt, stuur ik je graag opnieuw op pad om nog een vangst Spotted Yellowtail binnen te halen, $N. Met de ervaring die je de eerste keer hebt opgedaan, gaat deze vangst vast veel sneller en makkelijker. Doe je mee?",
  c = "Je bent een echt lid van de Alliance, $N. Je inzet zal niet onopgemerkt of ongewaardeerd blijven. En bedankt dat je de vis ook hebt gekookt. Ik zorg ervoor dat ze goed worden opgeborgen, en daarna moet ik mijn telling bijwerken. Elke vis brengt ons weer een stukje dichter bij het binnenhalen van ons doel.",
  g = { {"vangst", "catch, haul"}, {"binnen te halen", "to bring in (binnenhalen)"}, {"opgedaan", "gained (opdoen)"}, {"doe je mee", "are you game? (meedoen)"}, {"onopgemerkt", "unnoticed"}, {"ongewaardeerd", "unappreciated"}, {"opgeborgen", "stored away (opbergen)"}, {"telling", "count"}, {"bijwerken", "to update"}, {"binnenhalen", "bringing in, landing (a catch)"} },
},

[8793] = { en = "The Horde Needs Your Help!", tier = 4,
  t = "De Horde heeft je hulp nodig!",
  d = "Hallo, fijn dat je naar me wilt luisteren. De Horde heeft alle hulp nodig die ze kan krijgen om zich voor te bereiden op de Ahn'Qiraj-oorlog, en dat betekent dat we jou nodig hebben! Op dit moment verzamelen officiële verzamelaars al het materiaal dat nodig is voor de komende oorlog, maar zonder jouw hulp halen we onze doelen niet, $N!$B$BJe moet gaan praten met de man die de leiding heeft, Warlord Gorchuk. Wat zeg je ervan, $c? Help je mee met de belangrijke voorbereidingen?",
  o = "Praat met Warlord Gorchuk in Orgrimmar's Valley of Spirits.",
  c = "Throm'ka, $c! Fijn om zoveel leden van de Horde te zien, zoals jij, $N, die hun steun komen geven om het fundament te leggen voor de komende Ahn'Qiraj-oorlog. Dit werk zorgt ervoor dat we zullen winnen van de Silithid en hun kwaadaardige meesters, die zich verbergen in Ahn'Qiraj.$B$BNu je hier bent, moet je zeker met de verschillende verzamelaars praten. Bied je hulp aan bij het verzamelen van de materialen die bij jou passen.",
  g = { {"fijn", "nice, glad"}, {"zich voor te bereiden", "to prepare (zich voorbereiden)"}, {"Ahn'Qiraj-oorlog", "Ahn'Qiraj War"}, {"officiële", "official (officieel)"}, {"verzamelaars", "collectors (verzamelaar)"}, {"komende", "coming, upcoming (komend)"}, {"de leiding", "the lead, in charge"}, {"voorbereidingen", "preparations (voorbereiding)"}, {"steun", "support"}, {"het fundament te leggen", "to lay the groundwork"}, {"kwaadaardige", "evil (kwaadaardig)"}, {"verbergen", "to hide"}, {"bied", "offer (aanbieden)"} },
},

