[8850] = { en = "Thirty Signets for War Supplies", tier = 4,
  t = "Dertig zegels voor oorlogsvoorraden",
  o = "Goed, dan is het geregeld; hier zijn je voorraden, $c. Wil je nog een keer ruilen? Dan ben ik bereid daar toestemming voor te geven. Zeg het maar, en ik regel het.$B$BGa zo door, $N. We hebben al het materieel nodig dat we bij elkaar kunnen krijgen als we dit willen winnen. Als we allemaal ons deel doen, dan ligt de overwinning voor het grijpen!",
  p = "Ah, je komt dus extra voorraden voor jezelf halen? Nou, ik begrijp best dat je extra materieel nodig hebt... kijk maar om je heen als je bewijs wilt.$B$BIk geef je wat extra voorraden, maar dan moet je me in ruil een passend aantal Commendation Signets geven. Je krijgt geen erkenning als je de zegels op deze manier inlevert. Maar misschien vind je iets nuttigs dat je helpt om in leven te blijven als de strijd eindelijk begint.",
  c = "Goed, dan is het geregeld; hier zijn je voorraden, $c. Wil je nog een keer ruilen? Dan ben ik bereid daar toestemming voor te geven. Zeg het maar, en ik regel het.$B$BGa zo door, $N. We hebben al het materieel nodig dat we bij elkaar kunnen krijgen als we dit willen winnen. Als we allemaal ons deel doen, dan ligt de overwinning voor het grijpen!",
  g = { {"zegels", "signets, seals (zegel)"}, {"oorlogsvoorraden", "war supplies"}, {"geregeld", "settled (regelen)"}, {"ruilen", "to exchange, trade"}, {"bereid", "prepared, willing"}, {"toestemming", "permission, authorization"}, {"materieel", "materiel, equipment"}, {"voor het grijpen", "for the taking"}, {"passend", "appropriate"}, {"in ruil", "in exchange"}, {"erkenning", "recognition"}, {"inlevert", "hand in, surrender (inleveren)"} },
},

})

